import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 100 · Christmas recipe: overnight Christmas breakfast casserole

sc("""Sweetheart, on Christmas morning, the last thing anybody wants is to be stuck at the stove flipping pancakes while everybody else opens presents. That's why every grandmother I knew made a Christmas breakfast casserole the night before. You put it together on Christmas Eve, and in the morning, you just slide it in the oven. But most of them come out soggy in the middle, or dry and rubbery on top.""",
   "soggy breakfast casserole slice", "SOGGY IN THE MIDDLE")
sc("""So tonight I'm giving you my Christmas morning breakfast casserole, step by step, the one my family has eaten every Christmas since nineteen seventy-four. And the five mistakes that ruin it. Stay with me, because the last secret is what kind of bread you use, and why it has to be a little bit stale. Most people get that exactly backwards.""",
   "golden breakfast casserole Christmas morning", "A LITTLE BIT STALE")

ch("Christmas morning")
sc("""When my children were little, Christmas morning was chaos, honey. Paper everywhere, children screaming, Harold trying to put a bicycle together with the wrong screwdriver. And I was in the kitchen, missing all of it, making eggs and bacon for eight people. One year, Susan opened the doll she'd wanted for two years, and I didn't see her face. I was flipping pancakes. I cried in the kitchen.""",
   "1970s family Christmas morning paper mess", "I MISSED HER FACE")
sc("""The next December, my neighbor, Mrs. Kowalski, gave me her recipe for what she called a strata, an overnight egg and bread casserole. She said, Ruth, you make it on Christmas Eve, and you put it in the oven when the children wake up. And by the time the presents are open, breakfast is ready. And the cook gets to watch. It changed Christmas morning in our house forever.""",
   "neighbor giving handwritten recipe card", "THE COOK GETS TO WATCH")
sc("""Casseroles like this go back to the frugal cooks of the early nineteen hundreds, honey, who never threw away stale bread. Soak it in eggs and milk, bake it, and yesterday's bread becomes breakfast for a crowd. The Italians have strata, the French have pain perdu. In a minute I'll tell you why the stale bread is the most important part.""",
   "stale bread loaf on cutting board", "NEVER WASTE BREAD")

sc("""Mrs. Kowalski's recipe card is still in my recipe box, sweetheart, stained with fifty years of butter and egg. Her handwriting is in pencil, and at the bottom she wrote, Ruth, don't skimp on the cheese. I never have. She passed in nineteen ninety-one, and every Christmas morning, when I take this out of the oven, I say a little thank you to her. I've passed the card to my daughter now. A copy, of course. I'll never give away the original.""",
   "old stained recipe card in pencil", "DON'T SKIMP ON THE CHEESE")
ch("What you need")
sc("""Here's what you need for a nine by thirteen pan, which feeds about ten. One pound of breakfast sausage, or bacon, or diced ham. Eight cups of cubed bread, about one loaf. Two cups of shredded sharp cheddar. Ten eggs. Two and a half cups of milk. One teaspoon of dry mustard, one teaspoon of salt, half a teaspoon of pepper. And a few green onions.""",
   "eggs sausage bread cheese ingredients", "THE INGREDIENTS")
sc("""And here's mistake number one, the secret I promised you. Using soft, fresh sandwich bread. Fresh bread soaks up the eggs and turns into mush, like wet paper. You want a sturdy bread, like French bread, sourdough, or Italian, and it needs to be a day or two old. Stale bread is thirsty, honey. It drinks up the custard and holds its shape, so every bite is soft inside and crisp on top.""",
   "cubed stale French bread in bowl", "STALE BREAD")
sc("""If your bread is fresh, cut it into cubes, spread them on a baking sheet, and bake them at three hundred degrees for fifteen minutes until they're dry, but not brown. Let them cool. Or leave them out on the counter, uncovered, all day on Christmas Eve. That's what I do. The grandchildren know not to eat the bread cubes on the counter, or Grandma will get them.""",
   "bread cubes drying on baking sheet", "DRY THEM OUT")

sc("""And use real sharp cheddar that you grate yourself, honey. The pre-shredded cheese in the bag is coated with a powder to keep it from sticking, and it doesn't melt as smoothly. It turns a little grainy. A block of sharp cheddar costs about the same, and it takes two minutes to grate. Your casserole will be creamier, and the top will brown beautifully.""",
   "grating block of sharp cheddar", "GRATE YOUR OWN")
ch("Putting it together")
sc("""Cook the sausage in a skillet, breaking it up, until it's browned. And here's mistake number two. Not draining it. All that grease sinks to the bottom and makes the whole thing greasy and heavy. Drain it well on paper towels. If you're adding vegetables, like onions, peppers, mushrooms or spinach, cook them first, too. Raw vegetables let out water as they bake, and that's another soggy middle.""",
   "draining cooked sausage on paper towels", "DRAIN IT WELL")
sc("""If this is helping you, tap the like button for me, sweetheart. It helps Grandma more than you know. Butter your baking dish well. Spread half the bread cubes in the bottom. Sprinkle half the sausage and half the cheese over it. Then the rest of the bread, the rest of the sausage, and the rest of the cheese on top. Layers, honey, so every bite has a little of everything.""",
   "layering bread sausage cheese in dish", "LAYERS")
sc("""In a big bowl, whisk the eggs, milk, mustard, salt and pepper until it's completely smooth, with no streaks of egg white. Mistake number three is not whisking enough, and then you get rubbery white streaks of cooked egg. Pour it slowly and evenly over the whole dish. Then press down on the bread with the back of a spatula, so every cube gets a drink.""",
   "pouring egg custard over bread casserole", "PRESS IT DOWN")

ch("Overnight")
sc("""Cover it with foil, and put it in the icebox overnight. And that's mistake number four, honey. Not letting it sit long enough. It needs at least eight hours, so the bread soaks up all that custard all the way to the center. If you bake it right away, you get dry bread on top and a puddle of runny egg underneath. Overnight is the whole secret of the dish.""",
   "foil covered casserole in refrigerator", "OVERNIGHT")
sc("""And here's what I do on Christmas Eve, sweetheart. After the children are in bed, and the presents are under the tree, Harold and I would put this together at the kitchen table, with a glass of eggnog and the radio playing carols. It took twenty minutes. It became one of my favorite parts of Christmas, that quiet half hour in the kitchen, just the two of us.""",
   "couple in kitchen late Christmas Eve", "THE QUIET HALF HOUR")

sc("""If you have a houseful of company, honey, make two. They fit side by side in most ovens. And if you're feeding just two or three people, cut the recipe in half and use an eight-inch square dish. It bakes about ten minutes faster. I make a little one for Harold's sister every year and take it over on Christmas Eve, so she can have Christmas breakfast in her own kitchen.""",
   "two casseroles side by side in oven", "MAKE TWO")
ch("Christmas morning baking")
sc("""So far, stale bread, drained sausage, layers, a good whisk, and a night in the icebox. In the morning, when the first child wakes up, take the casserole out of the icebox and let it sit on the counter for thirty minutes while the oven heats to three hundred fifty. Mistake number five is putting it in ice cold. The outside burns before the middle cooks.""",
   "casserole on counter oven preheating morning", "THIRTY MINUTES ON THE COUNTER")
sc("""Bake it covered with foil for thirty minutes, then take off the foil and bake another twenty to thirty minutes, until the top is puffed and golden and a knife in the center comes out clean. Let it rest for ten minutes before cutting, so it sets. And while it bakes, honey, you go sit by the tree in your bathrobe with a cup of coffee and watch every single present get opened.""",
   "puffed golden breakfast casserole from oven", "PUFFED AND GOLDEN")

ch("Making it your own")
sc("""Once you know how, change it any way you like. Ham and Swiss with a little Dijon. Bacon and pepper jack with green chiles. Spinach, mushrooms and feta for the vegetarians. Or make a sweet one with cinnamon bread, cream cheese and blueberries, and pour maple syrup over the top. My grandchildren insist on two pans now, one savory and one sweet.""",
   "sweet cinnamon bread casserole with berries", "ONE SAVORY, ONE SWEET")
sc("""And serve it with something fresh and bright on the side, sweetheart. A bowl of oranges and grapefruit sections. A plate of sliced apples with cinnamon. And a pitcher of fresh orange juice. That's the whole Christmas breakfast, made ahead, with one dish to wash. My family has eaten it every Christmas morning for fifty years, and they'd riot if I changed it.""",
   "Christmas breakfast table with fruit and juice", "THEY'D RIOT")

sc("""And leftovers, if there are any, are wonderful, sweetheart. Cut them into squares, wrap each one in foil, and keep them in the icebox for four days or the freezer for two months. Warm a square in the oven or the microwave for a quick breakfast on a school morning. My grandson takes one to work every day the week after Christmas. He says it's the best part of the holidays.""",
   "square of casserole wrapped in foil", "THE LEFTOVERS")
ch("Grandma's kitchen")
sc("""So one more time. Use sturdy, stale bread, dried out if you need to. Drain the sausage and cook the vegetables. Layer it. Whisk the eggs until smooth and press the bread down. Let it sit overnight. Thirty minutes on the counter before baking. Foil on, then foil off. And then go sit by the tree, honey. You've earned it.""",
   "grandmother by Christmas tree with coffee", "GO SIT BY THE TREE")
sc("""Tell me in the comments, sweetheart. What does your family eat on Christmas morning? I'd love to know. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas morning kitchen sunlight", "WHAT DO YOU EAT?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma100", "Christmas Breakfast Casserole EVERYONE Makes WRONG (Why It's SOGGY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Strata, a layered bread-and-egg casserole, became popular in American home cooking in the 20th century as a way to use stale bread.",
      "Recipe as written by Grandma Ruth: 1 lb sausage, 8 cups stale bread cubes, 2 cups sharp cheddar, 10 eggs, 2 1/2 cups milk, 1 tsp dry mustard, 1 tsp salt, 1/2 tsp pepper, green onions; refrigerated overnight; 350F covered 30 min, uncovered 20-30 min."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
